int LivingWorldLogic::getNumHumanPlayers(bool includeEliminated)
{
	int count = 0;
	for (unsigned int i = 0; i < m_players.size(); ++i)
	{
		LivingWorldPlayer *player = m_players[i];
		if (player->m_kind == 0 && (!player->m_isEliminated || includeEliminated))
			++count;
	}
	return count;
}

