bool LivingWorldLogic::AdvanceTurnPhase()
{
	if (!IsCurrentTurnPhaseFinished() || m_turnPhase >= 6)
		return false;
	m_turnPhase = m_turnPhase + 1;
	m_unk0x104 = m_unk0x100;
	CheckTurnPhaseTransitions();
	return true;
}

